from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify and separate the groups of parentheses
    groups = []
    group = ""
    for char in paren_string:
        if char == "(":
            if group:
                groups.append(group)
            group = "("
        elif char == ")":
            group += ")"
            groups.append(group)
            group = ""

    # Step 3: Check if each group is balanced
    def is_balanced(group):
        stack = []
        for char in group:
            if char == "(":
                stack.append(char)
            elif char == ")":
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    # Step 4: Return the individual strings of balanced groups
    return [group for group in groups if is_balanced(group)]

